module benchmark/solution

export pure func isLeapYear(year: int) -> bool ! {}
ensures { result == ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) }
{
  (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

export pure func daysInMonth(month: int, year: int) -> int ! {}
requires { month >= 1, month <= 12 }
ensures { result >= 28, result <= 31 }
{
  if month == 2 then (if isLeapYear(year) then 29 else 28)
  else if month == 4 || month == 6 || month == 9 || month == 11 then 30
  else 31
}

export func main() -> () ! {IO} {
  println(show(isLeapYear(1900)));
  println(show(isLeapYear(2000)));
  println(show(isLeapYear(2024)));
  println(show(isLeapYear(2023)));
  println(show(daysInMonth(2, 2000)));
  println(show(daysInMonth(2, 1900)));
  println(show(daysInMonth(4, 2023)))
}

